def create_wire_and_verify(lib, cell, points):
    import pyAether as pyScript
    cv = pyScript.dbOpenCV(lib=lib, cell=cell, view="schematic")
    wire_figs = pyScript.dbCrtSchWire(cv=cv, point=points)
    if not wire_figs:
        return False
    return bool(pyScript.dbSchIsWire(wire_figs[0]))

def get_pin_name(cv, inst_name):
    import pyAether as pyScript
    fig = pyScript.dbFindInst(cv=cv, name=inst_name)
    if not fig:
        return None
    return pyScript.dbGetPinFigName(fig=fig)

def create_wire(lib, cell, points):
    import pyAether as pyScript
    cv = pyScript.dbOpenCV(lib=lib, cell=cell, view="schematic")
    return pyScript.dbCrtSchWire(cv=cv, point=points)

def get_pin_name(fig):
    import pyAether
    return pyAether.emyFigGetPinName(fig)
